        cur, prev = leaf, None
        while cur:
            parent = cur.parent
            old_left, old_right = cur.left, cur.right
            cur.left = parent
            cur.parent = prev
            if old_left and old_left is not prev:
                cur.right = old_left
            elif old_right is not prev:
                cur.right = old_right
            else:
                cur.right = None
            prev, cur = cur, parent
        return leaf

