class Solution:
    def flipBinaryTree(self, root: 'Node', leaf: 'Node') -> 'Node':
        path = []
        stack = [(root, False)]
        while stack:
            node, done = stack.pop()
            path.append(node)
            if node is leaf:
                break
            if not done:
                stack.append((node, True))
                if node.right:
                    stack.append((node.right, False))
                if node.left:
                    stack.append((node.left, False))
            else:
                path.pop()
        for i in range(len(path) - 1, -1, -1):
            cur = path[i]
            prev = path[i + 1] if i + 1 < len(path) else None
            parent = path[i - 1] if i > 0 else None
            old_left, old_right = cur.left, cur.right
            cur.left = parent
            cur.parent = prev
            if old_left and old_left is not prev:
                cur.right = old_left
            elif old_right is not prev:
                cur.right = old_right
            else:
                cur.right = None
        return leaf

