class Solution {
public:
    Node* flipBinaryTree(Node* root, Node* leaf) {
        vector<Node*> path;
        collect(root, leaf, path);
        for (int i = (int)path.size() - 1; i >= 0; i--) {
            Node* cur = path[i];
            Node* prev = i + 1 < (int)path.size() ? path[i + 1] : nullptr;
            Node* parent = i > 0 ? path[i - 1] : nullptr;
            Node* lft = cur->left;
            Node* rgt = cur->right;
            cur->left = parent;
            cur->parent = prev;
            if (lft && lft != prev) cur->right = lft;
            else if (rgt != prev) cur->right = rgt;
            else cur->right = nullptr;
        }
        return leaf;
    }
private:
    bool collect(Node* node, Node* leaf, vector<Node*>& path) {
        if (!node) return false;
        path.push_back(node);
        if (node == leaf || collect(node->left, leaf, path) || collect(node->right, leaf, path))
            return true;
        path.pop_back();
        return false;
    }
};

