class Solution {
    public Node flipBinaryTree(Node root, Node leaf) {
        List<Node> path = new ArrayList<>();
        collect(root, leaf, path);
        for (int i = path.size() - 1; i >= 0; i--) {
            Node cur = path.get(i);
            Node prev = i + 1 < path.size() ? path.get(i + 1) : null;
            Node parent = i > 0 ? path.get(i - 1) : null;
            Node lft = cur.left, rgt = cur.right;
            cur.left = parent;
            cur.parent = prev;
            if (lft != null && lft != prev) cur.right = lft;
            else if (rgt != prev) cur.right = rgt;
            else cur.right = null;
        }
        return leaf;
    }

    private boolean collect(Node node, Node leaf, List<Node> path) {
        if (node == null) return false;
        path.add(node);
        if (node == leaf || collect(node.left, leaf, path) || collect(node.right, leaf, path))
            return true;
        path.remove(path.size() - 1);
        return false;
    }
}

